// halea-design.js
// Halea polish (10 Oct): real glass, normal-case nav, lavender instead of lime,
// wordmark reveal, slower orbs. Fonts, halo, stars and light are kept as they are. Run from your project folder:
//     node halea-design.js
// Safe to run twice. Every file it changes is copied to .launch-backup/ first.

const fs = require('fs');
const path = require('path');

const ROOT = process.cwd();
const STAMP = new Date().toISOString().replace(/[:.]/g, '-');
const BACKUP = path.join(ROOT, '.launch-backup', 'design-' + STAMP);
const report = [];
const done = (m) => report.push(['DONE   ', m]);
const skip = (m) => report.push(['ALREADY', m]);
const warn = (m) => report.push(['CHECK  ', m]);

const FILES = {
  "app/(tabs)/_layout.tsx": "// app/(tabs)/_layout.tsx\n// Floating glass tab bar (Oct 10 reset).\n//   - Real glass on both platforms. iPhone uses the system blur. Android needs\n//     its blur switched on AND told what to blur: the whole navigator is wrapped\n//     in a BlurTargetView, and the bar's BlurView blurs that target.\n//   - One quiet \"you are here\" signal: a soft lavender pill behind the active\n//     tab. No dots, no glow.\n//   - Normal-case labels, one font, no letter-spacing, so nothing wraps.\n\nimport { useRef, type ReactElement, type RefObject } from 'react';\nimport { Tabs } from 'expo-router';\nimport { View, Text, StyleSheet, Platform } from 'react-native';\nimport { BlurView, BlurTargetView } from 'expo-blur';\nimport Svg, { Path, Circle } from 'react-native-svg';\nimport * as Haptics from 'expo-haptics';\n\nconst IDLE = 'rgba(255,254,247,0.55)';\nconst ACTIVE = '#FFFEF7';\n\n// ─── Icons (one stroke weight, one size) ──────────────────────────\nconst icon = (color: string, children: React.ReactNode) => (\n  <Svg width={22} height={22} viewBox=\"0 0 24 24\" fill=\"none\" stroke={color} strokeWidth={1.7} strokeLinecap=\"round\" strokeLinejoin=\"round\">\n    {children}\n  </Svg>\n);\nconst IconHome = ({ color }: { color: string }) => icon(color, <Path d=\"M3 10l9-7 9 7v10a2 2 0 01-2 2h-4v-6h-6v6H5a2 2 0 01-2-2z\" />);\nconst IconDiscover = ({ color }: { color: string }) => icon(color, <><Circle cx=\"11\" cy=\"11\" r=\"7.5\" /><Path d=\"M21 21l-4.3-4.3\" /></>);\nconst IconShop = ({ color }: { color: string }) => icon(color, <><Path d=\"M6 8h12l-1 12H7L6 8z\" /><Path d=\"M9 8V6a3 3 0 016 0v2\" /></>);\nconst IconMe = ({ color }: { color: string }) => icon(color, <><Circle cx=\"12\" cy=\"8\" r=\"4\" /><Path d=\"M4 21v-1a8 8 0 0116 0v1\" /></>);\n// Halea: the halo ring from the app icon\nconst IconHalea = ({ color }: { color: string }) => icon(color, <><Circle cx=\"12\" cy=\"12\" r=\"8.5\" /><Circle cx=\"12\" cy=\"12\" r=\"2.2\" fill={color} stroke=\"none\" /></>);\n\nfunction TabItem({ focused, label, Icon }: { focused: boolean; label: string; Icon: (p: { color: string }) => ReactElement }) {\n  const color = focused ? ACTIVE : IDLE;\n  return (\n    <View style={[styles.item, focused && styles.itemActive]}>\n      <Icon color={color} />\n      <Text numberOfLines={1} style={[styles.label, { color }]}>{label}</Text>\n    </View>\n  );\n}\n\n// Glass: system blur + a thin tint so the bar reads on any background\nfunction GlassBackground({ target }: { target: RefObject<View | null> }) {\n  return (\n    <View style={StyleSheet.absoluteFill}>\n      <BlurView\n        tint=\"dark\"\n        intensity={Platform.OS === 'ios' ? 45 : 60}\n        blurMethod=\"dimezisBlurViewSdk31Plus\"\n        blurTarget={target}\n        style={StyleSheet.absoluteFill}\n      />\n      <View style={[StyleSheet.absoluteFill, styles.glassTint]} />\n    </View>\n  );\n}\n\nconst haptic = () => { Haptics.selectionAsync().catch(() => {}); };\n\nexport default function TabLayout() {\n  const blurTarget = useRef<View | null>(null);\n\n  const tab = (label: string, Icon: (p: { color: string }) => ReactElement) => ({\n    tabBarIcon: ({ focused }: { focused: boolean }) => <TabItem focused={focused} label={label} Icon={Icon} />,\n    tabBarLabel: () => null,\n  });\n\n  return (\n    <Tabs\n      layout={({ children }) => (\n        <BlurTargetView ref={blurTarget} style={{ flex: 1 }}>\n          {children}\n        </BlurTargetView>\n      )}\n      screenOptions={{\n        headerShown: false,\n        tabBarShowLabel: false,\n        tabBarStyle: styles.tabBar,\n        tabBarBackground: () => <GlassBackground target={blurTarget} />,\n        tabBarIconStyle: styles.iconSlot,\n        tabBarItemStyle: styles.tabSlot,\n        tabBarHideOnKeyboard: true,\n      }}\n    >\n      <Tabs.Screen name=\"home\" listeners={{ tabPress: haptic }} options={tab('Home', IconHome)} />\n      <Tabs.Screen name=\"discover\" listeners={{ tabPress: haptic }} options={tab('Discover', IconDiscover)} />\n      <Tabs.Screen name=\"ai-chat\" listeners={{ tabPress: haptic }} options={tab('Halea', IconHalea)} />\n      <Tabs.Screen name=\"products\" listeners={{ tabPress: haptic }} options={tab('Shop', IconShop)} />\n      <Tabs.Screen name=\"profile\" listeners={{ tabPress: haptic }} options={tab('Me', IconMe)} />\n      {/* Not in the bar, still reachable from other screens */}\n      <Tabs.Screen name=\"salons\" options={{ href: null }} />\n      {/*__EXTRA_HIDDEN__*/}\n    </Tabs>\n  );\n}\n\nconst styles = StyleSheet.create({\n  tabBar: {\n    position: 'absolute',\n    left: 16,\n    right: 16,\n    bottom: Platform.OS === 'ios' ? 28 : 16,\n    height: 68,\n    paddingBottom: 0,\n    paddingTop: 0,\n    borderRadius: 34,\n    borderTopWidth: 0,\n    backgroundColor: 'transparent',\n    overflow: 'hidden',\n    elevation: 0,\n  },\n  glassTint: {\n    backgroundColor: 'rgba(26,16,56,0.38)',\n    borderRadius: 34,\n    borderWidth: StyleSheet.hairlineWidth,\n    borderColor: 'rgba(255,255,255,0.18)',\n  },\n  tabSlot: {\n    height: 68,\n    paddingTop: 0,\n    paddingBottom: 0,\n    justifyContent: 'center',\n    alignItems: 'center',\n  },\n  iconSlot: {\n    width: 62,\n    height: 54,\n  },\n  item: {\n    width: 62,\n    height: 54,\n    borderRadius: 27,\n    alignItems: 'center',\n    justifyContent: 'center',\n    gap: 3,\n  },\n  itemActive: {\n    backgroundColor: 'rgba(195,140,217,0.22)',\n  },\n  label: {\n    fontFamily: 'Sora_600SemiBold',\n    fontSize: 11,\n  },\n});\n",
  "app/index.tsx": "// app/index.tsx\n// Splash for returning users: the halea wordmark draws itself over the slow\n// orbs, fills with lavender, a small sparkle catches, then the tagline.\n// New visitors go straight to the intro, which has the same reveal.\n\nimport { useEffect, useRef } from 'react';\nimport { View, StyleSheet } from 'react-native';\nimport { useRouter } from 'expo-router';\nimport Animated, { FadeInUp } from 'react-native-reanimated';\nimport { supabase } from '@/lib/supabase';\nimport { HaleaWordmark } from '@/components/HaleaWordmark';\nimport { HaloBackground } from '@/components/HaloBackground';\nimport { FluidOrb } from '@/components/FluidOrb';\nimport { Colors } from '@/constants/theme';\n\nexport default function SplashScreen() {\n  const router = useRouter();\n  const signedIn = useRef<boolean | null>(null);\n  const revealDone = useRef(false);\n  const left = useRef(false);\n\n  const goHomeIfReady = () => {\n    if (left.current || !revealDone.current || signedIn.current !== true) return;\n    left.current = true;\n    setTimeout(() => router.replace('/(tabs)/home'), 700);\n  };\n\n  useEffect(() => {\n    let cancelled = false;\n    supabase.auth.getSession().then(({ data }) => {\n      if (cancelled) return;\n      if (!data.session) {\n        left.current = true;\n        router.replace('/onboarding');\n        return;\n      }\n      signedIn.current = true;\n      goHomeIfReady();\n    }).catch(() => { if (!cancelled) router.replace('/onboarding'); });\n    return () => { cancelled = true; };\n  }, []);\n\n  return (\n    <View style={styles.container}>\n      <HaloBackground />\n      <FluidOrb color={Colors.violet} size={620} top={-140} left={-160} spinDuration={18000} spinDirection={1} breatheDuration={4500} baseOpacity={0.42} />\n      <FluidOrb color={Colors.pink} size={480} top={260} left={40} spinDuration={22000} spinDirection={-1} breatheDuration={5200} baseOpacity={0.30} />\n      <View style={styles.center}>\n        <HaleaWordmark\n          width={230}\n          delay={250}\n          onDone={() => { revealDone.current = true; goHomeIfReady(); }}\n        />\n        <Animated.Text entering={FadeInUp.duration(600).delay(2350)} style={styles.tag}>\n          Step into your halo.\n        </Animated.Text>\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { flex: 1, backgroundColor: '#120B2E' },\n  center: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  tag: {\n    fontFamily: 'Fraunces_400Regular_Italic',\n    fontSize: 20,\n    color: 'rgba(255,254,247,0.8)',\n    marginTop: 22,\n  },\n});\n",
  "components/HaleaWordmark.tsx": "// components/HaleaWordmark.tsx\n// The \"halea\" wordmark in Plus Jakarta Sans ExtraBold, as fixed shapes so it\n// looks the same on every phone. Entrance: the outline of each letter draws\n// itself, the colour rises up to fill the letters, the outline fades, then a\n// small sparkle catches on the last letter.\n//\n//   <HaleaWordmark width=240 />            animated entrance\n//   <HaleaWordmark width=120 animate={false} />   static (headers)\n\nimport { useEffect } from 'react';\nimport { View } from 'react-native';\nimport Animated, {\n  useSharedValue, useAnimatedProps, useAnimatedStyle, withDelay, withTiming, withSequence, Easing,\n} from 'react-native-reanimated';\nimport type { SharedValue } from 'react-native-reanimated';\nimport Svg, { Path, G } from 'react-native-svg';\n\nconst AnimatedPath = Animated.createAnimatedComponent(Path);\n\nconst VB_W = 2516;\nconst VB_Y = -780;\nconst VB_H = 800;\n\nconst GLYPHS = [\n  { d: 'M55 0V-757H205V-438L187 -462Q206 -511 248.5 -534.5Q291 -558 348 -558Q410 -558 456.5 -532.0Q503 -506 529.0 -459.5Q555 -413 555 -351V0H405V-319Q405 -351 392.5 -374.0Q380 -397 357.5 -410.0Q335 -423 305 -423Q276 -423 253.0 -410.0Q230 -397 217.5 -374.0Q205 -351 205 -319V0Z', len: 3400 },\n  { d: 'M793 12Q734 12 691.0 -7.0Q648 -26 625.0 -61.5Q602 -97 602 -146Q602 -192 623.0 -227.5Q644 -263 687.5 -287.0Q731 -311 796 -321L963 -348V-238L823 -213Q791 -207 774.0 -192.5Q757 -178 757 -151Q757 -126 776.0 -112.0Q795 -98 823 -98Q860 -98 888.0 -114.0Q916 -130 931.5 -157.5Q947 -185 947 -218V-360Q947 -391 922.5 -412.0Q898 -433 856 -433Q816 -433 785.5 -411.0Q755 -389 741 -353L621 -410Q637 -456 672.0 -489.0Q707 -522 756.0 -540.0Q805 -558 863 -558Q932 -558 985.0 -533.0Q1038 -508 1067.5 -463.5Q1097 -419 1097 -360V0H957V-88L991 -94Q967 -58 938.0 -34.5Q909 -11 873.0 0.5Q837 12 793 12Z', len: 3438 },\n  { d: 'M1177 0V-757H1327V0Z', len: 1814 },\n  { d: 'M1670 12Q1583 12 1519.0 -26.5Q1455 -65 1420.0 -130.0Q1385 -195 1385 -274Q1385 -356 1421.5 -420.0Q1458 -484 1520.0 -521.0Q1582 -558 1660 -558Q1725 -558 1775.0 -537.5Q1825 -517 1859.5 -480.0Q1894 -443 1912.0 -394.5Q1930 -346 1930 -289Q1930 -273 1928.5 -257.5Q1927 -242 1923 -231H1514V-341H1838L1767 -289Q1777 -332 1766.0 -365.5Q1755 -399 1727.5 -418.5Q1700 -438 1660 -438Q1621 -438 1593.0 -419.0Q1565 -400 1551.0 -363.0Q1537 -326 1540 -273Q1536 -227 1551.0 -192.0Q1566 -157 1597.0 -137.5Q1628 -118 1672 -118Q1712 -118 1740.5 -134.0Q1769 -150 1785 -178L1905 -121Q1889 -81 1854.5 -51.0Q1820 -21 1773.0 -4.5Q1726 12 1670 12Z', len: 3549 },\n  { d: 'M2157 12Q2098 12 2055.0 -7.0Q2012 -26 1989.0 -61.5Q1966 -97 1966 -146Q1966 -192 1987.0 -227.5Q2008 -263 2051.5 -287.0Q2095 -311 2160 -321L2327 -348V-238L2187 -213Q2155 -207 2138.0 -192.5Q2121 -178 2121 -151Q2121 -126 2140.0 -112.0Q2159 -98 2187 -98Q2224 -98 2252.0 -114.0Q2280 -130 2295.5 -157.5Q2311 -185 2311 -218V-360Q2311 -391 2286.5 -412.0Q2262 -433 2220 -433Q2180 -433 2149.5 -411.0Q2119 -389 2105 -353L1985 -410Q2001 -456 2036.0 -489.0Q2071 -522 2120.0 -540.0Q2169 -558 2227 -558Q2296 -558 2349.0 -533.0Q2402 -508 2431.5 -463.5Q2461 -419 2461 -360V0H2321V-88L2355 -94Q2331 -58 2302.0 -34.5Q2273 -11 2237.0 0.5Q2201 12 2157 12Z', len: 3438 },\n];\n\ntype Props = {\n  width?: number;\n  color?: string;        // fill colour\n  outline?: string;      // outline colour while drawing\n  animate?: boolean;\n  delay?: number;        // ms before the entrance starts\n  sparkle?: boolean;\n  onDone?: () => void;   // called when the entrance finishes\n};\n\n// Timings (ms)\nconst DRAW = 1300;\nconst FILL_AT = 1000;\nconst FILL = 900;\nconst SPARKLE_AT = 2000;\n\nfunction Outline({ d, len, progress, color }: { d: string; len: number; progress: SharedValue<number>; color: string }) {\n  const props = useAnimatedProps(() => ({\n    strokeDashoffset: len * (1 - progress.value),\n  }));\n  return <AnimatedPath d={d} fill=\"none\" stroke={color} strokeWidth={14} strokeDasharray={[len, len]} animatedProps={props} />;\n}\n\nexport function HaleaWordmark({\n  width = 240, color = '#C38CD9', outline = '#C38CD9', animate = true, delay = 0, sparkle = true, onDone,\n}: Props) {\n  const height = (width * VB_H) / VB_W;\n  const draw = useSharedValue(animate ? 0 : 1);\n  const outlineOpacity = useSharedValue(animate ? 1 : 0);\n  const fill = useSharedValue(animate ? 0 : 1);\n  const spark = useSharedValue(animate ? 0 : 0.75);\n\n  useEffect(() => {\n    if (!animate) return;\n    const ease = Easing.inOut(Easing.cubic);\n    draw.value = withDelay(delay, withTiming(1, { duration: DRAW, easing: ease }));\n    fill.value = withDelay(delay + FILL_AT, withTiming(1, { duration: FILL, easing: Easing.out(Easing.cubic) }));\n    outlineOpacity.value = withDelay(delay + FILL_AT + FILL, withTiming(0, { duration: 500 }));\n    spark.value = withDelay(delay + SPARKLE_AT, withSequence(\n      withTiming(1, { duration: 380, easing: Easing.out(Easing.back(2)) }),\n      withTiming(0.75, { duration: 600 }),\n    ));\n    if (onDone) {\n      const t = setTimeout(onDone, delay + SPARKLE_AT + 400);\n      return () => clearTimeout(t);\n    }\n  }, []);\n\n  // Colour rises from the bottom: a clipping box that grows upward\n  const fillBox = useAnimatedStyle(() => ({ height: height * fill.value }));\n  const outlineStyle = useAnimatedStyle(() => ({ opacity: outlineOpacity.value }));\n  const sparkStyle = useAnimatedStyle(() => ({\n    opacity: spark.value,\n    transform: [{ scale: 0.4 + spark.value * 0.6 }, { rotate: `${spark.value * 90}deg` }],\n  }));\n\n  const s = Math.max(10, width * 0.06); // sparkle size\n  return (\n    <View style={{ width, height }}>\n      {/* Filled letters, revealed bottom-up */}\n      <Animated.View style={[{ position: 'absolute', left: 0, right: 0, bottom: 0, overflow: 'hidden' }, fillBox]}>\n        <Svg width={width} height={height} viewBox={`0 ${VB_Y} ${VB_W} ${VB_H}`} style={{ position: 'absolute', bottom: 0 }}>\n          <G fill={color}>\n            {GLYPHS.map((g, i) => <Path key={i} d={g.d} />)}\n          </G>\n        </Svg>\n      </Animated.View>\n\n      {/* Outline that draws itself */}\n      {animate && (\n        <Animated.View style={[{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0 }, outlineStyle]} pointerEvents=\"none\">\n          <Svg width={width} height={height} viewBox={`0 ${VB_Y} ${VB_W} ${VB_H}`}>\n            {GLYPHS.map((g, i) => <Outline key={i} d={g.d} len={g.len} progress={draw} color={outline} />)}\n          </Svg>\n        </Animated.View>\n      )}\n\n      {/* Small four-point sparkle above the final \"a\" */}\n      {sparkle && (\n        <Animated.View pointerEvents=\"none\" style={[{ position: 'absolute', width: s, height: s, right: -s * 0.55, top: -s * 0.35 }, sparkStyle]}>\n          <Svg width={s} height={s} viewBox=\"0 0 24 24\">\n            <Path d=\"M12 0 C12.8 7.5 16.5 11.2 24 12 C16.5 12.8 12.8 16.5 12 24 C11.2 16.5 7.5 12.8 0 12 C7.5 11.2 11.2 7.5 12 0 Z\" fill=\"#FFFEF7\" />\n          </Svg>\n        </Animated.View>\n      )}\n    </View>\n  );\n}\n"
};
const BINARIES = {"assets/halea-icon.png":"","assets/halea-adaptive-foreground.png":""};

const abs = (p) => path.join(ROOT, p);
const exists = (p) => fs.existsSync(abs(p));
function backup(p) {
  if (!exists(p)) return;
  const to = path.join(BACKUP, p);
  fs.mkdirSync(path.dirname(to), { recursive: true });
  fs.copyFileSync(abs(p), to);
}
function read(p) {
  const raw = fs.readFileSync(abs(p), 'utf8');
  return { text: raw.replace(/\r\n/g, '\n'), crlf: raw.includes('\r\n') };
}
function write(p, text, crlf) {
  fs.mkdirSync(path.dirname(abs(p)), { recursive: true });
  fs.writeFileSync(abs(p), crlf ? text.replace(/\n/g, '\r\n') : text, 'utf8');
}
function edit(file, label, steps) {
  if (!exists(file)) return warn(`${label}: ${file} not found. Skipped.`);
  const { text, crlf } = read(file);
  let out = text, changed = 0, already = 0, missing = 0;
  for (const st of steps) {
    const isDone = st.doneIf && (typeof st.doneIf === 'string' ? out.includes(st.doneIf) : st.doneIf.test(out));
    if (isDone) { already++; continue; }
    const hit = typeof st.find === 'string' ? out.includes(st.find) : st.find.test(out);
    if (!hit) { if (!st.optional) missing++; continue; }
    out = typeof st.find === 'string' ? out.split(st.find).join(st.replace) : out.replace(st.find, st.replace);
    changed++;
  }
  if (changed) { backup(file); write(file, out, crlf); }
  if (missing) warn(`${label}: ${missing} change(s) didn't match your version of ${file}. Send me that file.`);
  else if (changed) done(label);
  else if (already) skip(label);
}

if (!exists('package.json') || !exists('app')) {
  console.error('\nRun this from your Halea project folder (the one with package.json and the app folder).\n');
  process.exit(1);
}

// ─── 1. New and replaced files ─────────────────────────────────────
const tabFiles = exists('app/(tabs)')
  ? fs.readdirSync(abs('app/(tabs)')).filter((f) => /\.tsx?$/.test(f) && !f.startsWith('_')).map((f) => f.replace(/\.tsx?$/, ''))
  : [];
const KNOWN_TABS = ['home', 'discover', 'ai-chat', 'products', 'profile', 'salons'];

for (const [p, original] of Object.entries(FILES)) {
  let content = original;
  if (p === 'app/(tabs)/_layout.tsx') {
    // Only declare tabs that exist on this laptop; keep any extra screens hidden
    content = content.split('\n').filter((line) => {
      const m = line.match(/<Tabs\.Screen name="([^"]+)"/);
      return !m || tabFiles.includes(m[1]);
    }).join('\n');
    const extra = tabFiles.filter((n) => !KNOWN_TABS.includes(n));
    content = content.replace('      {/*__EXTRA_HIDDEN__*/}',
      extra.map((n) => `      <Tabs.Screen name="${n}" options={{ href: null }} />`).join('\n'));
    if (extra.length) warn(`Nav: these screens are not in the bar (hidden but still work): ${extra.join(', ')}. Tell me if one should be a tab.`);
  }
  if (exists(p) && read(p).text === content) { skip(`File ${p}`); continue; }
  const existed = exists(p);
  backup(p);
  write(p, content, false);
  done(`${existed ? 'Replaced' : 'Added'} ${p}`);
}

for (const [p, b64] of Object.entries(BINARIES)) {
  const buf = Buffer.from(b64, 'base64');
  if (exists(p) && fs.readFileSync(abs(p)).equals(buf)) { skip(`File ${p}`); continue; }
  backup(p);
  fs.mkdirSync(path.dirname(abs(p)), { recursive: true });
  fs.writeFileSync(abs(p), buf);
  done(`Added ${p}`);
}

// ─── 3. Intro screen: wordmark reveal, calm button ────────────────
edit('app/onboarding.tsx', 'Intro: new wordmark reveal', [
  {
    find: /<View style=\{s\.nameRow\}>[\s\S]*?<\/View>/,
    replace: '<HaleaWordmark width={250} delay={500} />',
    doneIf: '<HaleaWordmark',
  },
  {
    find: "import { HaloBackground } from '@/components/HaloBackground';",
    replace: "import { HaloBackground } from '@/components/HaloBackground';\nimport { HaleaWordmark } from '@/components/HaleaWordmark';",
    doneIf: "from '@/components/HaleaWordmark'",
  },
  { find: /const NAME_DONE = [^\n;]+;/, replace: 'const NAME_DONE = 2700; // when the wordmark reveal finishes', doneIf: 'const NAME_DONE = 2700' },
  { find: /\n([ \t]*)Step into your halo\n/, replace: '\n$1Step into your halo.\n', doneIf: /\n[ \t]*Step into your halo\.\n/, optional: true },
]);

// ─── 4. Lime is gone: lavender takes its place ────────────────────
{
  const dirs = ['app', 'components', 'constants', 'lib'];
  let files = 0, hits = 0;
  const walk = (d) => {
    if (!exists(d)) return;
    for (const f of fs.readdirSync(abs(d))) {
      const p = path.join(d, f);
      if (fs.statSync(abs(p)).isDirectory()) { walk(p); continue; }
      if (!/\.(ts|tsx)$/.test(f)) continue;
      const { text, crlf } = read(p);
      const out = text
        .replace(/#D9FF00/gi, '#C38CD9')
        .replace(/rgba\(\s*217\s*,\s*255\s*,\s*0\s*,/g, 'rgba(195,140,217,');
      if (out !== text) {
        hits += (text.match(/#D9FF00|rgba\(\s*217\s*,\s*255\s*,\s*0\s*,/gi) || []).length;
        backup(p); write(p, out, crlf); files++;
      }
    }
  };
  dirs.forEach(walk);
  if (files) done(`Lime replaced with lavender (${hits} places in ${files} files)`);
  else skip('No lime left');
}

// ─── 5. Orbs slowed: still alive, no longer busy ─────────────────
edit('components/FluidOrb.tsx', 'Orbs slowed down (same look, calmer motion)', [
  {
    find: /(export function FluidOrb\(\{[\s\S]*?\}: Props\) \{\n)/,
    replace: '$1  // Personality, but calm: never faster than one turn every 18s or one breath every 4.5s\n  spinDuration = Math.max(spinDuration, 18000);\n  breatheDuration = Math.max(breatheDuration, 4500);\n',
    doneIf: 'Math.max(spinDuration, 18000)',
  },
]);

// ─── 6. Try-on: saving works, no "AI" or "4K" labels ──────────────
edit('app/hairtransfer.tsx', 'Try-on: Save to gallery fixed, plain titles', [
  { find: "from 'expo-file-system';", replace: "from 'expo-file-system/legacy';", doneIf: "from 'expo-file-system/legacy'" },
  { find: '>AI Hair Try-On<', replace: '>Try a style<', doneIf: '>Try a style<', optional: true },
  { find: '>Generated at 4K resolution with AI<', replace: '>Your new look<', doneIf: '>Your new look<', optional: true },
]);

// ─── 7. Icon and app colours ──────────────────────────────────────
if (exists('app.json')) {
  const cfg = JSON.parse(read('app.json').text);
  const e = cfg.expo;
  const before = JSON.stringify(e);
  e.icon = './assets/halea-icon.png';
  e.android = e.android || {};
  e.android.adaptiveIcon = { ...(e.android.adaptiveIcon || {}), foregroundImage: './assets/halea-adaptive-foreground.png', backgroundColor: '#120B2E' };
  e.splash = { ...(e.splash || {}), backgroundColor: '#120B2E' };
  if (JSON.stringify(e) !== before) { backup('app.json'); write('app.json', JSON.stringify(cfg, null, 2) + '\n', false); done('app.json: new icon, dark purple splash'); }
  else skip('app.json icon settings');
}

console.log('\nHalea design reset\n');
for (const [tag, msg] of report) console.log(`  ${tag}  ${msg}`);
if (fs.existsSync(BACKUP)) console.log(`\nBackups: ${path.relative(ROOT, BACKUP)}`);
console.log('\nNext: npx expo start --dev-client -c\n');
